import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { DocumentPage } from "./src/DocumentPage" with { type: "ref" };
import { userSignupFields } from "./src/auth" with { type: "ref" };
import { webSocketFn } from "./src/webSocket" with { type: "ref" };

import { getDocuments, getDocument, getPermissions } from "./src/queries" with { type: "ref" };
import { createDocument, saveVersion, restoreVersion, shareDocument, revokePermission } from "./src/actions" with { type: "ref" };

export default app({
  name: "app",
  title: "Real-time Collaborative Document Editor",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
    onAuthSucceededRedirectTo: "/",
  },
  webSocket: {
    fn: webSocketFn,
    autoConnect: true,
  },
  spec: [
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("DocumentRoute", "/document/:id", page(DocumentPage, { authRequired: true })),

    query(getDocuments, { entities: ["Document", "Permission"] }),
    query(getDocument, { entities: ["Document", "Permission", "Version", "User"] }),
    query(getPermissions, { entities: ["Permission", "User", "Document"] }),

    action(createDocument, { entities: ["Document"] }),
    action(saveVersion, { entities: ["Document", "Version", "Permission"] }),
    action(restoreVersion, { entities: ["Document", "Version", "Permission"] }),
    action(shareDocument, { entities: ["Document", "Permission", "User"] }),
    action(revokePermission, { entities: ["Permission", "Document"] }),
  ],
});

import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  username: (data: any) => {
    if (typeof data.username !== "string" || !data.username.trim()) {
      throw new Error("Username is required");
    }
    return data.username.trim();
  },
});

import { Server, Socket } from "socket.io";

let globalIo: Server | null = null;

export const webSocketFn = (io: Server, context: any) => {
  globalIo = io;

  io.on("connection", (socket: Socket) => {
    const user = socket.data.user;
    const username = user?.username ?? "Unknown";
    console.log(`User connected: ${username} (ID: ${user?.id})`);

    socket.on("joinDocument", ({ documentId }) => {
      const room = `document-${documentId}`;
      socket.join(room);
      console.log(`Socket ${socket.id} (user: ${username}) joined room ${room}`);
    });

    socket.on("updateDocument", async ({ documentId, content }) => {
      const docId = Number(documentId);
      if (isNaN(docId)) return;

      try {
        // Permissions check: does the user have edit/owner access?
        if (!user) {
          console.warn("Unauthenticated attempt to update document");
          return;
        }

        const doc = await context.entities.Document.findUnique({
          where: { id: docId },
          include: { permissions: true },
        });

        if (!doc) {
          console.warn(`Document ${docId} not found for update`);
          return;
        }

        const isOwner = doc.ownerId === user.id;
        const hasEditPermission = doc.permissions.some(
          (p: any) => p.userId === user.id && p.role === "EDIT"
        );

        if (!isOwner && !hasEditPermission) {
          console.warn(`User ${username} denied edit access to document ${docId}`);
          return;
        }

        // Update document content in the database
        await context.entities.Document.update({
          where: { id: docId },
          data: { content },
        });

        // Broadcast change to other users in the room
        socket.to(`document-${docId}`).emit("documentContentChanged", { content });
      } catch (error) {
        console.error("Error in updateDocument socket handler:", error);
      }
    });

    socket.on("disconnect", () => {
      console.log(`User disconnected: ${username}`);
    });
  });
};

export const getIo = () => globalIo;

import { HttpError } from "wasp/server";

export const getDocuments = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: context.user.id },
        { permissions: { some: { userId: context.user.id } } },
      ],
    },
    include: {
      owner: true,
    },
    orderBy: { updatedAt: "desc" },
  });
};

export const getDocument = async ({ id }: { id: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }

  const docId = Number(id);
  if (isNaN(docId)) {
    throw new HttpError(400, "Invalid document ID");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
    include: {
      owner: true,
      versions: {
        include: { author: true },
        orderBy: { createdAt: "desc" },
      },
      permissions: {
        include: { user: true },
      },
    },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = document.ownerId === context.user.id;
  const userPermission = document.permissions.find(
    (p: any) => p.userId === context.user.id
  );

  if (!isOwner && !userPermission) {
    throw new HttpError(403, "Access Denied");
  }

  const role = isOwner ? "OWNER" : userPermission.role;

  return { document, role };
};

export const getPermissions = async ({ documentId }: { documentId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }

  const docId = Number(documentId);
  if (isNaN(docId)) {
    throw new HttpError(400, "Invalid document ID");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: docId },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  if (document.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can view permissions");
  }

  return context.entities.Permission.findMany({
    where: { documentId: docId },
    include: { user: true },
  });
};

import { HttpError } from "wasp/server";
import { getIo } from "./webSocket";

export const createDocument = async ({ title }: { title: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }
  if (!title || !title.trim()) {
    throw new HttpError(400, "Title is required");
  }
  return context.entities.Document.create({
    data: {
      title: title.trim(),
      ownerId: context.user.id,
      content: "",
    },
  });
};

export const saveVersion = async (
  { documentId, content }: { documentId: number; content: string },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }

  const docId = Number(documentId);
  const doc = await context.entities.Document.findUnique({
    where: { id: docId },
    include: { permissions: true },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p: any) => p.userId === context.user.id && p.role === "EDIT"
  );

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Only owner or users with EDIT permission can save a version");
  }

  // Update document primary content
  const updatedDoc = await context.entities.Document.update({
    where: { id: docId },
    data: { content },
  });

  // Create version
  const version = await context.entities.Version.create({
    data: {
      documentId: docId,
      content,
      authorId: context.user.id,
    },
  });

  // Broadcast the update to all other WebSocket clients
  const io = getIo();
  if (io) {
    io.to(`document-${docId}`).emit("documentContentChanged", { content });
  }

  return version;
};

export const restoreVersion = async (
  { documentId, versionId }: { documentId: number; versionId: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }

  const docId = Number(documentId);
  const verId = Number(versionId);

  const doc = await context.entities.Document.findUnique({
    where: { id: docId },
    include: { permissions: true },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p: any) => p.userId === context.user.id && p.role === "EDIT"
  );

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Only owner or users with EDIT permission can restore a version");
  }

  const version = await context.entities.Version.findUnique({
    where: { id: verId },
  });

  if (!version || version.documentId !== docId) {
    throw new HttpError(404, "Version not found for this document");
  }

  // Update document primary content
  const updatedDoc = await context.entities.Document.update({
    where: { id: docId },
    data: { content: version.content },
  });

  // Broadcast the change to all active WebSocket clients immediately
  const io = getIo();
  if (io) {
    io.to(`document-${docId}`).emit("documentContentChanged", { content: version.content });
  }

  return updatedDoc;
};

export const shareDocument = async (
  { documentId, username, role }: { documentId: number; username: string; role: string },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }

  const docId = Number(documentId);
  const doc = await context.entities.Document.findUnique({
    where: { id: docId },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can share the document");
  }

  if (role !== "VIEW" && role !== "EDIT") {
    throw new HttpError(400, "Invalid role. Must be 'VIEW' or 'EDIT'");
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: username.trim() },
  });

  if (!targetUser) {
    throw new HttpError(404, `User '${username}' not found`);
  }

  if (targetUser.id === context.user.id) {
    throw new HttpError(400, "You cannot share the document with yourself");
  }

  // Create or update permission
  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId: docId,
        userId: targetUser.id,
      },
    },
    update: { role },
    create: {
      documentId: docId,
      userId: targetUser.id,
      role,
    },
  });
};

export const revokePermission = async (
  { documentId, userId }: { documentId: number; userId: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "User not authenticated");
  }

  const docId = Number(documentId);
  const targetUserId = Number(userId);

  const doc = await context.entities.Document.findUnique({
    where: { id: docId },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can revoke permissions");
  }

  return context.entities.Permission.delete({
    where: {
      documentId_userId: {
        documentId: docId,
        userId: targetUserId,
      },
    },
  });
};

